import{_ as i,a0 as l,w as r,s as p,ao as d,I as s,a1 as o,A as n,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Fedora 36 工作站中啓用最小化和最大化按鈕 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 36 工作站中啓用最小化和最大化按鈕 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 36 工作站中啓用最小化和最大化按鈕 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 36 工作站中啓用最小化和最大化按鈕 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220514 How To Enable Minimize And Maximize Buttons In Fedora 36 Workstation","title":"如何在 Fedora 36 工作站中啓用最小化和最大化按鈕","tag":"202205","desc":""},"relativePath":"202205/20220514 How To Enable Minimize And Maximize Buttons In Fedora 36 Workstation.md","filePath":"[post].md"}'),h={name:"202205/20220514 How To Enable Minimize And Maximize Buttons In Fedora 36 Workstation.md"};function m(u,e,g,b,x,f){const t=l("Link");return r(),p("div",null,[e[16]||(e[16]=d('<h1 id="如何在-fedora-36-工作站中啓用最小化和最大化按鈕" tabindex="-1">如何在 Fedora 36 工作站中啓用最小化和最大化按鈕 <a class="header-anchor" href="#如何在-fedora-36-工作站中啓用最小化和最大化按鈕" aria-label="Permalink to “如何在 Fedora 36 工作站中啓用最小化和最大化按鈕”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/22/151018fjxtiidtrztri0rr.jpg" alt=""></p><blockquote><p>今天，我們將看到 Fedora 桌面的安裝後步驟之一。這個簡短的指南解釋瞭如何在 Fedora GNOME 工作站和 Silverblue 版本的應用窗口中啓用最小化和最大化按鈕。</p></blockquote><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>你可能已經知道，Fedora Silverblue 和 Fedora GNOME 工作站版本的應用窗口中沒有最小化和最大化按鈕。</p><p>如果要最小化應用窗口，需要右鍵單擊其標題欄並從上下文菜單中選擇最小化選項。</p><p>不幸的是，你甚至無法在 Firefox 中使用鼠標獲得該選項。要最小化 Firefox 窗口，你要點擊 <code>左 ALT+空格</code> 鍵並選擇最小化選項。</p><p>我不知道隱藏最常用的按鈕有什麼好處。Ubuntu GNOME 桌面有最小/最大按鈕，但 Fedora 沒有。</p><p>如果你想恢復 Fedora GNOME 和 Silverblue 版本中的最小化和最大化按鈕，你可以藉助 Fedora 中的 <strong>Gnome Tweaks</strong> 程序和 “Dash to Panel” 擴展來啓用它們。</p><h3 id="在-fedora-中安裝-gnome-tweaks" tabindex="-1">在 Fedora 中安裝 Gnome Tweaks <a class="header-anchor" href="#在-fedora-中安裝-gnome-tweaks" aria-label="Permalink to “在 Fedora 中安裝 Gnome Tweaks”">​</a></h3><p><strong>Gnome Tweaks</strong>，以前稱為 <strong>Tweak Tool</strong>，是用於高級 GNOME 3 設置的圖形界面。它主要是為 GNOME Shell 設計的，但也可以在其他桌面中使用。如果你在不同的桌面上使用 Tweaks，你可能無法擁有所有功能。它在 Fedora 的默認倉庫中可用。因此，你可以使用 <code>dnf</code> 包管理器在 Fedora 上安裝 Gnome Tweaks，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gnome-tweaks</span></span></code></pre></div><p>如果你使用 Fedora Silverblue，你需要使用以下命令進入你的 toolbox 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ toolbox enter</span></span></code></pre></div><p>然後按照前面的命令安裝 Tweaks。</p><h3 id="在瀏覽器中添加-gnome-shell-集成插件" tabindex="-1">在瀏覽器中添加 Gnome Shell 集成插件 <a class="header-anchor" href="#在瀏覽器中添加-gnome-shell-集成插件" aria-label="Permalink to “在瀏覽器中添加 Gnome Shell 集成插件”">​</a></h3><p>確保你在瀏覽器中添加了 “Gnome Shell 集成” 插件。此擴展提供與 GNOME shell 和相應擴展倉庫的集成。</p><p>如果你尚未添加它，請轉到插件頁並搜索並安裝它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Add-Gnome-Shell-Integration-Add-on-In-Firefox-Browser.png" alt="Add Gnome Shell Integration Add-on In Firefox Browser"></p><p>將出現一個彈出窗口。單擊“添加”以啓用加載項。添加此擴展程序後，你將在瀏覽器的工具欄上看到 GNOME 圖標。</p><h3 id="在-fedora-中啓用-dash-到面板擴展" tabindex="-1">在 Fedora 中啓用 Dash 到面板擴展 <a class="header-anchor" href="#在-fedora-中啓用-dash-到面板擴展" aria-label="Permalink to “在 Fedora 中啓用 Dash 到面板擴展”">​</a></h3><p>“Dash to panel” 擴展是 Gnome Shell 的圖標任務欄。此擴展將 dash 移動到 GNOME 主面板中，以便將應用啓動器和系統托盤組合到一個面板中，類似於 KDE Plasma 和 Windows 7 以上操作系統中的面板。</p><p>“Dash to panel” 擴展為你提供了一個永久可見的面板，其中包含最喜歡的快捷方式。因此，不再需要單獨的停靠區來輕鬆訪問正在運行和收藏的應用。</p><p>要啓用 “Dash to panel” 擴展，請進入 GNOME 擴展站點並搜索 “Dash to panel” 擴展。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Search-for-Dash-to-panel-extension-in-Gnome-extensions-site.png" alt="Search for Dash to panel extension in Gnome extensions site"></p><p>單擊搜索結果中的 “Dash to panel” 鏈接。你將被重定向到 “Dash to panel” 擴展的官方頁面。點擊 “ON” 按鈕。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Enable-Dash-to-panel-extension.png" alt="Enable Dash to panel extension"></p><p>在下一個窗口中，單擊安裝按鈕以啓用 “Dash to panel” 擴展。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Install-Dash-to-panel-extension.png" alt="Install Dash to panel extension"></p><p>激活此擴展程序後，你將在底部看到 Dash 面板以及你最喜歡的快捷方式。</p><h3 id="在-fedora-中啓用最小化和最大化按鈕" tabindex="-1">在 Fedora 中啓用最小化和最大化按鈕 <a class="header-anchor" href="#在-fedora-中啓用最小化和最大化按鈕" aria-label="Permalink to “在 Fedora 中啓用最小化和最大化按鈕”">​</a></h3><p>打開 Gnome Tweaks 應用。進入 “<ruby>窗口標題欄<rt>Windows Titlebars</rt></ruby>” 並打開最小/最大按鈕。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Enable-Minimize-And-Maximize-Buttons-In-Application-Windows-In-Fedora.png" alt="Enable minimize and maximize buttons in application windows in Fedora"></p><p>當你打開開關後，最小化和最大化按鈕將出現在所有應用的窗口中。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Minimize-maximize-buttons-appears-in-applications-windows-in-Fedora.png" alt="Minimize, maximize buttons appears in applications windows in Fedora"></p><p>默認情況下，最小/最大按鈕在右側可見。你可以將其位置更改為左側或右側。</p><p>“Dash to panel” 擴展有很多微調和自定義選項。右鍵單擊 Dash 面板並選擇設置選項，然後根據你的喜好開始對其進行自定義。</p><h3 id="資源" tabindex="-1">資源 <a class="header-anchor" href="#資源" aria-label="Permalink to “資源”">​</a></h3>',38)),s("blockquote",null,[s("p",null,[s("strong",null,[o(t,{href:"https://extensions.gnome.org/extension/1160/dash-to-panel/"},{default:n(()=>[...e[0]||(e[0]=[a("Dash to panel 網站",-1)])]),_:1})])])]),e[17]||(e[17]=s("hr",null,null,-1)),s("p",null,[e[2]||(e[2]=a("via: ",-1)),o(t,{href:"https://ostechnix.com/how-to-enable-minimize-and-maximize-buttons-in-fedora/"},{default:n(()=>[...e[1]||(e[1]=[a("https://ostechnix.com/how-to-enable-minimize-and-maximize-buttons-in-fedora/",-1)])]),_:1})]),s("p",null,[e[7]||(e[7]=a("作者：",-1)),o(t,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>[...e[3]||(e[3]=[a("sk",-1)])]),_:1}),e[8]||(e[8]=a(" 選題：",-1)),o(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[4]||(e[4]=[a("lkxed",-1)])]),_:1}),e[9]||(e[9]=a(" 譯者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:n(()=>[...e[5]||(e[5]=[a("geekpi",-1)])]),_:1}),e[10]||(e[10]=a(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=a("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[a("Linux中國",-1)])]),_:1}),e[15]||(e[15]=a(" 榮譽推出",-1))])])}const c=i(h,[["render",m]]);export{T as __pageData,c as default};
